    <script>
        let characterList = [];
        let currentIndex = 0;
        let characterData = null;

        function SafeGetValue(obj, path, defaultValue = "...") {
            if (obj === null || obj === undefined) return defaultValue;
            let keys = Array.isArray(path) ? path : path.split('.');
            let current = obj;
            for (let i = 0; i < keys.length; i++) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                    return defaultValue;
                }
                current = current[keys[i]];
            }
            if (current === undefined || current === null) return defaultValue;
            if (Array.isArray(current)) {
                return current.length > 0 ? current[0] : defaultValue;
            }
            return current;
        }

        function updateProgressBar(barId, valId, rawValue, min, max) {
            const bar = document.getElementById(barId);
            const valSpan = document.getElementById(valId);
            if (!bar || !valSpan) return;
            let numVal = parseFloat(SafeGetValue({ d: rawValue }, 'd', String(min)));
            numVal = Math.max(min, Math.min(max, numVal));
            valSpan.innerText = Math.round(numVal);
            const percentage = max > min ? ((numVal - min) / (max - min)) * 100 : 0;
            bar.style.width = `${percentage}%`;
        }

        function updateGoodwillBar(labelId, barId, permanentVal, tempVal, min, max) {
            const bar = document.getElementById(barId);
            const label = document.getElementById(labelId);
            if (!bar || !label) return;
            let permNum = parseFloat(SafeGetValue({ d: permanentVal }, 'd', String(min)));
            let tempNum = parseFloat(SafeGetValue({ d: tempVal }, 'd', '0'));
            permNum = Math.round(Math.max(min, Math.min(max, permNum)));
            tempNum = Math.round(tempNum);

            label.innerText = `好感度: ${permNum}` + (tempNum > 0 ? ` (+${tempNum})` : '') + ` / ${max}`;
            const percentage = max > min ? ((permNum - min) / (max - min)) * 100 : 0;
            bar.style.width = `${percentage}%`;
        }

        function updateBodyPart(elementId, bodyPartData) {
            const el = document.getElementById(elementId);
            if (el) {
                if (!bodyPartData || SafeGetValue(bodyPartData, '装备', '') === "N/A") {
                    el.innerHTML = '<span style="opacity:0.5">N/A</span>';
                    return;
                }
                const equip = SafeGetValue(bodyPartData, '装备', '无');
                const state = SafeGetValue(bodyPartData, '状态', '...');
                el.innerHTML = `<span class="mvu-equip">${equip}</span><br><span class="mvu-state">${state}</span>`;
            }
        }

        function updatePlayerUI(playerData) {
            if (!playerData) return;
            document.getElementById('player-name').innerText = `玩家状态: ${SafeGetValue(playerData, '姓名', '...')}`;
            document.getElementById('player-identity').innerText = SafeGetValue(playerData, '身份');
            const sequenceName = SafeGetValue(playerData, '序列.名称', '普通人');
            const sequenceRank = SafeGetValue(playerData, '序列.等级', null);
            document.getElementById('player-sequence').innerText = sequenceRank !== null ? `${sequenceName} (Seq. ${sequenceRank})` : sequenceName;
            document.getElementById('player-money').innerText = `${SafeGetValue(playerData, '金钱', 0)} 信用点`;
            const skills = `社交 ${SafeGetValue(playerData, '技能.社交', 0)} | 观察 ${SafeGetValue(playerData, '技能.观察', 0)} | 神秘学 ${SafeGetValue(playerData, '技能.神秘学知识', 0)}`;
            document.getElementById('player-skills').innerText = skills;
            const items = SafeGetValue(playerData, '物品', []);
            document.getElementById('player-items').innerText = items.length > 0 ? items.join(', ') : '无';
        }

        function updateCharacterUI(charName) {
            if (!characterData || !characterData.角色 || !characterData.角色[charName]) return;
            const char = characterData.角色[charName];
            const isNonHuman = char.双乳 && SafeGetValue(char.双乳, '装备', '') === "N/A";

            document.getElementById('char-name').innerText = charName;
            document.getElementById('char-location').innerText = `【${SafeGetValue(char, '位置', '未知地点')}】`;
            document.getElementById('char-age').innerText = `年龄: ${SafeGetValue(char, '年龄', '?')}`;
            document.getElementById('char-pregnancy').innerText = isNonHuman ? '怀孕: N/A' : `怀孕：${SafeGetValue(char, '妊娠状态', '未知')}`;

            updateGoodwillBar('char-goodwill-label', 'char-goodwill-bar', char.好感度, char.好感度临时池, 0, 100);
            updateProgressBar('char-stability-bar', 'char-stability-val', char.关系稳固度, 0, 100);
            updateProgressBar('char-lust-bar', 'char-lust-val', char.性欲值, 0, 100);

            const emotion = `${SafeGetValue(char, '情绪状态.主要')} (${SafeGetValue(char, '情绪状态.次要')})`;
            document.getElementById('char-emotion').innerText = emotion;
            document.getElementById('char-clothing').innerText = SafeGetValue(char, '当前衣着', '未知');
            document.getElementById('char-goal').innerText = SafeGetValue(char, '短期目标', '...');
            document.getElementById('char-thought').innerText = SafeGetValue(char, '内心独白', '...');
            document.getElementById('char-status').innerText = SafeGetValue(char, '当前状态', '...');

            document.getElementById('char-body-status').style.display = isNonHuman ? 'none' : 'grid';
            updateBodyPart('char-breasts', char.双乳);
            updateBodyPart('char-pussy', char.小穴);
            updateBodyPart('char-anus', char.菊穴);
        }

        function updateWorldUI(worldData) {
            if (!worldData) return;
            const date = SafeGetValue(worldData, '日期', '');
            const day = SafeGetValue(worldData, '星期', '');
            const time = SafeGetValue(worldData, '时间', '');
            const period = SafeGetValue(worldData, '时段', '');
