            document.getElementById('time-header').innerText = `【${date} ${day} ${period} ${time} | ${weather}】`;
            document.getElementById('news-header').innerText = `新闻: ${SafeGetValue(worldData, '城市新闻', '无')}`;
        }

        function updateDisplay(data) {
            if (!data) return;
            characterData = data;
            characterList = SafeGetValue(characterData, '角色.列表', []);
            currentIndex = parseInt(SafeGetValue(characterData, '世界.当前显示角色索引', '0'), 10);

            if (isNaN(currentIndex) || currentIndex < 0 || currentIndex >= characterList.length) {
                currentIndex = 0;
            }

            updateWorldUI(characterData.世界);
            updatePlayerUI(characterData.玩家);

            if (characterList.length > 0) {
                updateCharacterUI(characterList[currentIndex]);
            } else {
                document.getElementById('char-name').innerText = "无角色列表";
            }
        }

        async function initDisplay() {
            try {

                var msgID = getCurrentMessageId();


                const messages = await getChatMessages(msgID);
                if (!messages || messages.length === 0) {
                    console.error("MVU Error: Chat history is empty or inaccessible.");
                    document.getElementById('char-name').innerText = "无聊天记录";
                    return;
                }

                let dataToDisplay = null;
                for (let i = messages.length - 1; i >= 0; i--) {
                    const msg = messages[i];
                    if (msg && msg.data && msg.data.stat_data) {
                        dataToDisplay = msg.data.stat_data;
                        break;
                    }
                }

                if (dataToDisplay) {
                    updateDisplay(dataToDisplay);
                } else {
                    if (msgID <= 1 && num <= 10) {
                        num++;
                        document.getElementById('char-name').innerText = "等待数据初始化……";
                        await new Promise(resolve => setTimeout(resolve, 50));
                        initDisplay();
                        return;
                    }
                    console.error("MVU Error: No valid stat_data found in recent messages.");
                    document.getElementById('char-name').innerText = "无有效数据";
                }

            } catch (error) {
                console.error("MVU Status bar error:", error);
                document.getElementById('char-name').innerText = "脚本执行错误";
            }
        }

        function switchCharacter(direction) {
            if (!characterData || characterList.length === 0) return;
            const oldIndex = currentIndex;

            currentIndex += direction;
            if (currentIndex < 0) { currentIndex = characterList.length - 1; }
            else if (currentIndex >= characterList.length) { currentIndex = 0; }

            // OPTIMIZED: Write back the index change to the backend.
            _.set('世界.当前显示角色索引', oldIndex, currentIndex);

            // Update UI immediately for responsiveness
            updateCharacterUI(characterList[currentIndex]);
        }



        var num = 0;

        // Initial load
        document.addEventListener('DOMContentLoaded', initDisplay);



        // ADDED: Event listener for real-time updates from the backend
        //SillyTavern.addEventListener('mag_variable_update_ended', initDisplay);


        document.getElementById('prev-char').addEventListener('click', () => switchCharacter(-1));
        document.getElementById('next-char').addEventListener('click', () => switchCharacter(1));

    </script>
